import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.BgftbQsK.js";const k=JSON.parse('{"title":"SSH — Remote Access from MacBook","description":"Set up SSH key authentication, SSH config shortcuts, server hardening, port forwarding for database access, and VS Code Remote SSH development.","frontmatter":{"title":"SSH — Remote Access from MacBook","order":5,"description":"Set up SSH key authentication, SSH config shortcuts, server hardening, port forwarding for database access, and VS Code Remote SSH development.","head":[["meta",{"name":"og:title","content":"SSH — Remote Access from MacBook | Ubuntu Home Lab Server"}],["meta",{"property":"og:description","content":"Set up SSH key authentication, SSH config shortcuts, server hardening, port forwarding for database access, and VS Code Remote SSH development."}]]},"headers":[],"relativePath":"chapters/05-ssh-remote-access-from-macbook.md","filePath":"chapters/05-ssh-remote-access-from-macbook.md","lastUpdated":null}'),t={name:"chapters/05-ssh-remote-access-from-macbook.md"};function l(p,s,r,o,h,c){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h2 id="how-ssh-works-the-concept" tabindex="-1">How SSH Works (The Concept) <a class="header-anchor" href="#how-ssh-works-the-concept" aria-label="Permalink to &quot;How SSH Works (The Concept)&quot;">​</a></h2><p>SSH (Secure Shell) creates an encrypted tunnel between your Mac and your server. Think of it as a secure pipeline — everything you type travels through this encrypted channel, so even if someone intercepts your WiFi packets, they see only gibberish.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your MacBook                    Your Server</span></span>
<span class="line"><span>┌──────────┐   Encrypted      ┌──────────┐</span></span>
<span class="line"><span>│ Terminal │ ◄───────────────► │  sshd    │</span></span>
<span class="line"><span>│          │   SSH Tunnel     │ (daemon) │</span></span>
<span class="line"><span>└──────────┘   Port 22        └──────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>sshd</code> (SSH daemon) is the server-side process that listens on port 22 and accepts connections. You enabled this during installation when you checked &quot;Install OpenSSH&quot;.</p><h2 id="step-1-find-your-server-s-ip" tabindex="-1">Step 1: Find Your Server&#39;s IP <a class="header-anchor" href="#step-1-find-your-server-s-ip" aria-label="Permalink to &quot;Step 1: Find Your Server&#39;s IP&quot;">​</a></h2><p>On the server, right after installation:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or simpler:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Look for something like <code>192.168.1.105</code> — this is your server&#39;s current IP on your home network. We&#39;ll make this permanent in Chapter 6.</p><h2 id="step-2-first-ssh-connection" tabindex="-1">Step 2: First SSH Connection <a class="header-anchor" href="#step-2-first-ssh-connection" aria-label="Permalink to &quot;Step 2: First SSH Connection&quot;">​</a></h2><p>On your <strong>MacBook</strong>:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin@192.168.1.105</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>First time, you&#39;ll see:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The authenticity of host &#39;192.168.1.105&#39; can&#39;t be established.</span></span>
<span class="line"><span>ED25519 key fingerprint is SHA256:abc123...</span></span>
<span class="line"><span>Are you sure you want to continue connecting (yes/no)?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Type <code>yes</code>. This saves the server&#39;s <strong>fingerprint</strong> to <code>~/.ssh/known_hosts</code> on your Mac. Next time, SSH verifies the server is the same machine (prevents man-in-the-middle attacks).</p><h2 id="step-3-ssh-key-authentication-—-no-more-passwords" tabindex="-1">Step 3: SSH Key Authentication — No More Passwords <a class="header-anchor" href="#step-3-ssh-key-authentication-—-no-more-passwords" aria-label="Permalink to &quot;Step 3: SSH Key Authentication — No More Passwords&quot;">​</a></h2><p>Password authentication is less secure and annoying. SSH keys use <strong>asymmetric cryptography</strong>:</p><ul><li>You have a <strong>private key</strong> (stays on your Mac, NEVER share this)</li><li>You have a <strong>public key</strong> (goes on the server, safe to share)</li><li>The server challenges you with something only the private key can answer</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># On your MacBook — generate a key pair</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;macbook-homelab-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -t ed25519: modern elliptic curve algorithm (better than RSA)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -C: comment to identify the key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Accept defaults (saves to ~/.ssh/id_ed25519)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set a passphrase for extra security (optional but recommended)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>This creates two files:</p><ul><li><code>~/.ssh/id_ed25519</code> — Your private key (guard this like a password)</li><li><code>~/.ssh/id_ed25519.pub</code> — Your public key (copy this to server)</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy public key to server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin@192.168.1.105</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># This appends your public key to ~/.ssh/authorized_keys on the server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Now test — it should connect without asking for a password:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin@192.168.1.105</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="step-4-ssh-config-—-shortcuts-and-options" tabindex="-1">Step 4: SSH Config — Shortcuts and Options <a class="header-anchor" href="#step-4-ssh-config-—-shortcuts-and-options" aria-label="Permalink to &quot;Step 4: SSH Config — Shortcuts and Options&quot;">​</a></h2><p>Create/edit <code>~/.ssh/config</code> on your <strong>MacBook</strong>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># ~/.ssh/config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Host homelab</span></span>
<span class="line"><span>    HostName 192.168.1.100      # Will be your static IP from Chapter 6</span></span>
<span class="line"><span>    User labadmin</span></span>
<span class="line"><span>    IdentityFile ~/.ssh/id_ed25519</span></span>
<span class="line"><span>    ServerAliveInterval 60      # Send keepalive every 60 seconds</span></span>
<span class="line"><span>    ServerAliveCountMax 3       # Disconnect after 3 missed keepalives</span></span>
<span class="line"><span>    Compression yes             # Compress data (faster on WiFi)</span></span>
<span class="line"><span>    ForwardAgent no             # Don&#39;t forward SSH agent (security)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Now you can connect with just:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="step-5-hardening-ssh-on-the-server" tabindex="-1">Step 5: Hardening SSH on the Server <a class="header-anchor" href="#step-5-hardening-ssh-on-the-server" aria-label="Permalink to &quot;Step 5: Hardening SSH on the Server&quot;">​</a></h2><p>Edit the SSH server config:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Change these settings:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable password authentication (once keys work!)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PasswordAuthentication</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Don&#39;t allow root login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PermitRootLogin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Only allow your user</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AllowUsers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labadmin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use only modern key types</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PubkeyAuthentication</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change default port (optional but reduces bot spam)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Port 2222   ← uncomment to use non-standard port</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Disable unused features</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X11Forwarding</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AllowTcpForwarding</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Keep yes — needed for port forwarding</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Timeout idle sessions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ClientAliveInterval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ClientAliveCountMax</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><p>Apply changes:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sshd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>CRITICAL:</strong> Do NOT close your current SSH session until you verify a new session works. Open a second terminal and test <code>ssh homelab</code>. If it works, you&#39;re safe. If not, you still have your old session to fix things.</p></div><h2 id="ssh-port-forwarding-—-access-server-services-from-mac" tabindex="-1">SSH Port Forwarding — Access Server Services from Mac <a class="header-anchor" href="#ssh-port-forwarding-—-access-server-services-from-mac" aria-label="Permalink to &quot;SSH Port Forwarding — Access Server Services from Mac&quot;">​</a></h2><p>This is incredibly useful. It lets you access any port on your server as if it was on your Mac:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Access server&#39;s PostgreSQL (port 5432) locally on Mac</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5432:localhost:5432</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Now on your Mac, connect to localhost:5432 with TablePlus/DBeaver</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># It actually connects to the server&#39;s Postgres through the SSH tunnel</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Access pgAdmin (port 5050) locally</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5050:localhost:5050</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Open http://localhost:5050 in your Mac browser</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Forward multiple ports at once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5432:localhost:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5050:localhost:5050</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:localhost:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> homelab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="vs-code-remote-ssh-—-full-ide-on-server" tabindex="-1">VS Code Remote SSH — Full IDE on Server <a class="header-anchor" href="#vs-code-remote-ssh-—-full-ide-on-server" aria-label="Permalink to &quot;VS Code Remote SSH — Full IDE on Server&quot;">​</a></h2><p>Install the <strong>Remote - SSH</strong> extension in VS Code on your Mac:</p><ol><li><code>Cmd+Shift+P</code> → &quot;Remote-SSH: Connect to Host&quot;</li><li>Select <code>homelab</code></li><li>VS Code opens a new window connected to your server</li><li>You can open <code>/srv/myapp</code>, edit files, use the integrated terminal, debug</li></ol><p>This is the most productive way to develop on a remote server. Everything works exactly like local development.</p>`,43)])])}const u=a(t,[["render",l]]);export{k as __pageData,u as default};
